/**
 * Finance → Expenses (Phase 1, owner 2026-10-25): the rules, words and shapes
 * the Expenses tab uses, kept out of ExpensesTab.tsx so the component file
 * exports only components and the rules can be unit-tested.
 *
 * Data: migration 20261230100000_expenses_ledger.sql — tables expense_categories,
 * expense_vendors, expenses, read through get_expense_book(p_month) and written
 * only through upsert_expense / attach_expense_receipt / approve_expense /
 * void_expense (permission-checked, audited). None of these are in
 * src/integrations/supabase/types.ts yet (it is regenerated by Lovable, never
 * hand-edited — CLAUDE.md), hence the local types.
 *
 * Money: each expense keeps its own currency; every total reads amount_jpy,
 * which the database sets with the one peso rate (JPY = PHP ÷ php_jpy_rate).
 * Only APPROVED rows count in totals; drafts are shown separately; void rows
 * count nowhere.
 */

export const EXPENSE_BOOK_KEY = ["expense-book"] as const;
export const EXPENSE_RECEIPT_BUCKET = "expense-receipts";

export type ExpenseGroupKey =
  | "people" | "cost_of_goods" | "marketing" | "payment_fees"
  | "shipping" | "tech" | "office" | "professional";

/** The owner's eight groups, in the order she listed them. */
export const EXPENSE_GROUPS: { key: ExpenseGroupKey; label: string }[] = [
  { key: "people", label: "People" },
  { key: "cost_of_goods", label: "Cost of goods" },
  { key: "marketing", label: "Selling and marketing" },
  { key: "payment_fees", label: "Payment and banking fees" },
  { key: "shipping", label: "Shipping and logistics" },
  { key: "tech", label: "Tech and subscriptions" },
  { key: "office", label: "Office and premises" },
  { key: "professional", label: "Professional and government" },
];

export function groupLabel(key: string): string {
  return EXPENSE_GROUPS.find((g) => g.key === key)?.label ?? key;
}

export type ExpenseStatus = "draft" | "approved" | "void";
export type ExpenseCurrency = "JPY" | "PHP";
export type PaymentMethod = "bank_transfer" | "card" | "cash" | "auto_debit" | "other";

export const PAYMENT_METHODS: { value: PaymentMethod; label: string }[] = [
  { value: "bank_transfer", label: "Bank transfer" },
  { value: "card", label: "Card" },
  { value: "cash", label: "Cash" },
  { value: "auto_debit", label: "Auto-debit" },
  { value: "other", label: "Other" },
];

export function paymentMethodLabel(v: string): string {
  return PAYMENT_METHODS.find((m) => m.value === v)?.label ?? v;
}

export const STATUS_LABEL: Record<ExpenseStatus, string> = {
  draft: "Draft",
  approved: "Approved",
  void: "Void",
};

export interface ExpenseCategory {
  id: string;
  group_key: ExpenseGroupKey;
  name: string;
  sort_order: number;
  active: boolean;
  system_key: string | null;
}

export interface ExpenseVendor {
  id: string;
  name: string;
  default_category_id: string | null;
}

export interface Expense {
  id: string;
  expense_date: string;
  category_id: string;
  category_name: string;
  group_key: ExpenseGroupKey;
  vendor_id: string | null;
  vendor_name: string | null;
  description: string;
  currency: ExpenseCurrency;
  amount: number;
  fx_php_per_jpy: number | null;
  amount_jpy: number;
  payment_method: PaymentMethod;
  /** Ledger account that paid it (Phase 2b, 1xxx bank / cash / clearing); null until set. */
  paid_from?: string | null;
  receipt_path: string | null;
  status: ExpenseStatus;
  source: string;
  notes: string | null;
  /** Breakdown behind an automatic booking (payroll / commission lines); null for hand entries. */
  details: Record<string, unknown> | null;
  approved_at: string | null;
  voided_at: string | null;
  void_reason: string | null;
  created_at: string;
}

export interface ExpenseBook {
  month: string;
  can_manage: boolean;
  can_approve: boolean;
  php_jpy_rate: number | null;
  categories: ExpenseCategory[];
  vendors: ExpenseVendor[];
  expenses: Expense[];
}

export type ExpenseBookState =
  | { available: true; book: ExpenseBook }
  | { available: false };

/** Numbers arrive from jsonb as numbers or numeric strings; normalise once. */
export function normaliseBook(raw: Record<string, unknown>): ExpenseBook {
  const num = (v: unknown): number => (v == null || v === "" ? 0 : Number(v));
  const expenses = ((raw.expenses ?? []) as Record<string, unknown>[]).map((e) => ({
    ...(e as unknown as Expense),
    amount: num(e.amount),
    amount_jpy: num(e.amount_jpy),
    fx_php_per_jpy: e.fx_php_per_jpy == null ? null : Number(e.fx_php_per_jpy),
  }));
  return {
    month: String(raw.month ?? ""),
    can_manage: raw.can_manage === true,
    can_approve: raw.can_approve === true,
    php_jpy_rate: raw.php_jpy_rate == null ? null : Number(raw.php_jpy_rate),
    categories: (raw.categories ?? []) as ExpenseCategory[],
    vendors: (raw.vendors ?? []) as ExpenseVendor[],
    expenses,
  };
}

// ── Months ──────────────────────────────────────────────────────────────────

/** A `?month=YYYY-MM` deep link (from the Mark as paid panel) or null when absent/invalid. */
export function monthFromSearch(search: string): string | null {
  const v = new URLSearchParams(search).get("month");
  return v && /^\d{4}-(0[1-9]|1[0-2])$/.test(v) ? v : null;
}

/** Rows of an automatic booking's breakdown, for the Details expand. */
export function detailLines(details: Record<string, unknown> | null): { name: string; meta: string; amount: number }[] {
  if (!details || !Array.isArray(details.lines)) return [];
  const kind = String(details.kind ?? "");
  return (details.lines as Record<string, unknown>[]).map((l) => {
    const n = (k: string) => Number(l[k] ?? 0);
    if (kind === "payroll") {
      return {
        name: String(l.name ?? ""),
        meta: `${l.template === "csr" ? "CSR" : "Live Admin"} · ${n("total_hours").toFixed(1)} h`,
        amount: n("net"),
      };
    }
    return {
      name: String(l.name ?? ""),
      meta: `${l.role_won ?? "—"}${l.top_sales ? " ★" : ""} · earn ₱${n("earn").toLocaleString("en-US")} · bonus ₱${n("bonus").toLocaleString("en-US")}`,
      amount: n("total"),
    };
  });
}

/** "YYYY-MM" for a Date, in Japan time (the books are Cha Jewels Japan's). */
export function monthKeyTokyo(d: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Tokyo", year: "numeric", month: "2-digit" })
    .formatToParts(d);
  const y = parts.find((p) => p.type === "year")?.value ?? "1970";
  const m = parts.find((p) => p.type === "month")?.value ?? "01";
  return `${y}-${m}`;
}

/** Today as YYYY-MM-DD in Japan time — the default expense date. */
export function todayTokyo(d: Date = new Date()): string {
  return new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Tokyo", year: "numeric", month: "2-digit", day: "2-digit" })
    .format(d);
}

export function shiftMonth(key: string, delta: number): string {
  const [y, m] = key.split("-").map(Number);
  const idx = y * 12 + (m - 1) + delta;
  const ny = Math.floor(idx / 12);
  const nm = (idx % 12) + 1;
  return `${ny}-${String(nm).padStart(2, "0")}`;
}

export function monthLabel(key: string): string {
  const [y, m] = key.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, 1)).toLocaleDateString("en-GB", { month: "long", year: "numeric", timeZone: "UTC" });
}

// ── Money ───────────────────────────────────────────────────────────────────

export function formatYen(n: number): string {
  return `¥${Math.round(n).toLocaleString("en-US")}`;
}

export function formatAmount(amount: number, currency: ExpenseCurrency): string {
  if (currency === "JPY") return formatYen(amount);
  const r = Math.round(amount * 100) / 100;
  const s = r % 1 === 0
    ? r.toLocaleString("en-US")
    : r.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `₱${s}`;
}

/**
 * The JPY the database will store for a draft, shown in the form before saving.
 * Same rule as expenses_before_write: JPY = PHP ÷ rate, rounded. Never multiply.
 */
export function previewJpy(amount: number, currency: ExpenseCurrency, rate: number | null): number | null {
  if (!Number.isFinite(amount) || amount <= 0) return null;
  if (currency === "JPY") return Math.round(amount);
  if (rate == null || !(rate > 0)) return null;
  return Math.round(amount / rate);
}

export interface GroupTotal {
  key: ExpenseGroupKey;
  label: string;
  approvedJpy: number;
  draftJpy: number;
  approvedCount: number;
  draftCount: number;
}

/** Per-group and overall totals. Approved counts; drafts are separate; void is ignored. */
export function totalsByGroup(expenses: Expense[]): { groups: GroupTotal[]; approvedJpy: number; draftJpy: number } {
  const groups: GroupTotal[] = EXPENSE_GROUPS.map((g) => ({
    key: g.key, label: g.label, approvedJpy: 0, draftJpy: 0, approvedCount: 0, draftCount: 0,
  }));
  let approvedJpy = 0;
  let draftJpy = 0;
  for (const e of expenses) {
    const g = groups.find((x) => x.key === e.group_key);
    if (!g) continue;
    if (e.status === "approved") {
      g.approvedJpy += e.amount_jpy;
      g.approvedCount += 1;
      approvedJpy += e.amount_jpy;
    } else if (e.status === "draft") {
      g.draftJpy += e.amount_jpy;
      g.draftCount += 1;
      draftJpy += e.amount_jpy;
    }
  }
  return { groups, approvedJpy, draftJpy };
}

// ── Filters ─────────────────────────────────────────────────────────────────

export type StatusFilter = "all" | ExpenseStatus;

export type SourceFilter = "all" | "manual" | "payroll" | "commission" | "recurring" | "email" | "system";

export const SOURCE_FILTERS: { value: SourceFilter; label: string }[] = [
  { value: "all", label: "All sources" },
  { value: "manual", label: "By hand" },
  { value: "payroll", label: "Payroll" },
  { value: "commission", label: "Commission" },
];

export function sourceLabel(s: string): string {
  return SOURCE_FILTERS.find((x) => x.value === s)?.label ?? s;
}

export interface ExpenseFilters {
  status: StatusFilter;
  group: "all" | ExpenseGroupKey;
  source: SourceFilter;
  search: string;
}

export function filterExpenses(expenses: Expense[], f: ExpenseFilters): Expense[] {
  const q = f.search.trim().toLowerCase();
  return expenses.filter((e) => {
    if (f.status !== "all" && e.status !== f.status) return false;
    if (f.group !== "all" && e.group_key !== f.group) return false;
    if (f.source !== "all" && e.source !== f.source) return false;
    if (!q) return true;
    return [e.description, e.vendor_name ?? "", e.category_name, e.notes ?? ""]
      .some((s) => s.toLowerCase().includes(q));
  });
}

// ── Form ────────────────────────────────────────────────────────────────────

/** The add/edit form as text inputs. vendor: an existing id, or a new name typed in. */
export interface ExpenseForm {
  id: string | null;
  expense_date: string;
  category_id: string;
  vendor_id: string;
  new_vendor_name: string;
  description: string;
  currency: ExpenseCurrency;
  amount: string;
  payment_method: PaymentMethod;
  /** Ledger account code the money left from ("" = not set). Saved with set_expense_paid_from after the upsert. */
  paid_from: string;
  notes: string;
}

export function emptyExpenseForm(today: string = todayTokyo()): ExpenseForm {
  return {
    id: null, expense_date: today, category_id: "", vendor_id: "", new_vendor_name: "",
    description: "", currency: "JPY", amount: "", payment_method: "bank_transfer", paid_from: "", notes: "",
  };
}

export function formFromExpense(e: Expense): ExpenseForm {
  return {
    id: e.id,
    expense_date: e.expense_date,
    category_id: e.category_id,
    vendor_id: e.vendor_id ?? "",
    new_vendor_name: "",
    description: e.description,
    currency: e.currency,
    amount: String(e.amount),
    payment_method: e.payment_method,
    paid_from: e.paid_from ?? "",
    notes: e.notes ?? "",
  };
}

/** Phase 2b: an expense's "Paid from" account is required unless it was paid in cash. */
export function paidFromProblem(f: Pick<ExpenseForm, "payment_method" | "paid_from">, accountsAvailable: boolean): string | null {
  if (!accountsAvailable) return null;
  if (f.payment_method === "cash") return null;
  if (!f.paid_from) return "Pick which bank or account paid this.";
  return null;
}

/** Keep digits and at most one dot; JPY is whole yen, PHP has up to 2 decimals. */
export function cleanAmountInput(raw: string, currency: ExpenseCurrency): string {
  const s = raw.replace(/[^\d.]/g, "");
  if (currency === "JPY") return s.replace(/\./g, "");
  const [whole, ...rest] = s.split(".");
  if (rest.length === 0) return whole;
  return `${whole}.${rest.join("").slice(0, 2)}`;
}

/** First problem with the form, in plain words, or null when it can be saved. */
export function validateExpenseForm(f: ExpenseForm): string | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(f.expense_date)) return "Pick the date.";
  if (!f.category_id) return "Pick a category.";
  if (!f.description.trim()) return "Write what it was for.";
  if (f.description.trim().length > 500) return "Keep the description under 500 characters.";
  const n = Number(f.amount);
  if (!f.amount || !Number.isFinite(n) || n <= 0) return "Enter the amount.";
  if (f.currency === "JPY" && !Number.isInteger(n)) return "Yen amounts are whole yen.";
  if (f.notes.length > 2000) return "Keep the notes under 2,000 characters.";
  if (f.new_vendor_name.trim().length > 120) return "Keep the vendor name under 120 characters.";
  return null;
}

export function expensePayload(f: ExpenseForm): Record<string, string | null> {
  const newVendor = f.vendor_id ? "" : f.new_vendor_name.trim();
  return {
    id: f.id,
    expense_date: f.expense_date,
    category_id: f.category_id,
    vendor_id: f.vendor_id || null,
    new_vendor_name: newVendor || null,
    description: f.description.trim(),
    currency: f.currency,
    amount: f.amount,
    payment_method: f.payment_method,
    notes: f.notes.trim() || null,
  };
}

/** The server's refusal codes, in words staff can act on. */
export function expenseRefusal(code: string): string {
  switch (code) {
    case "permission_denied": return "You don't have permission for this. Ask an admin (Settings → Matrix → Expenses).";
    case "user_identity_required": return "Your sign-in has expired. Sign in again.";
    case "invalid_input": return "Something in the form could not be read. Check the date and amount.";
    case "invalid_date": return "The date is not valid.";
    case "invalid_category": return "Pick a category.";
    case "invalid_description": return "Write what it was for (up to 500 characters).";
    case "invalid_currency": return "Pick yen or pesos.";
    case "invalid_amount": return "The amount is not valid. Yen amounts are whole yen.";
    case "invalid_payment_method": return "Pick how it was paid.";
    case "invalid_notes": return "The notes are too long.";
    case "invalid_vendor": return "That vendor can't be used. Pick one from the list or type a new name.";
    case "not_draft": return "Only drafts can be changed. An approved expense can only be voided.";
    case "not_found": return "That expense no longer exists. Refresh the page.";
    case "reason_required": return "Write a reason (at least 3 characters).";
    case "already_void": return "This expense is already void.";
    case "invalid_receipt_path": return "The receipt could not be attached. Try uploading it again.";
    case "rate_not_set": return "The peso rate is not set in the Hub, so a peso expense can't be approved yet.";
    case "category_booked_automatically": return "Staff payroll and Sales commission are booked from Timesheet and Commissions, not by hand.";
    default: return "Something went wrong. Try again in a moment.";
  }
}

/**
 * Categories booked automatically (Phase 2: Timesheet / Commissions). upsert_expense refuses
 * them (category_booked_automatically) because a manual row would count the same money twice.
 */
export const AUTO_BOOKED_SYSTEM_KEYS = ["payroll", "commission"];

export function canEnterManually(c: { active: boolean; system_key: string | null }): boolean {
  return c.active && !(c.system_key != null && AUTO_BOOKED_SYSTEM_KEYS.includes(c.system_key));
}

/** Receipt files the bucket accepts (same list as the migration). Max 10 MB. */
export const RECEIPT_TYPES = ["image/jpeg", "image/png", "image/webp", "image/heic", "image/heif", "application/pdf"];
export const RECEIPT_MAX_BYTES = 10 * 1024 * 1024;

const RECEIPT_TYPE_BY_EXT: Record<string, string> = {
  jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", webp: "image/webp",
  heic: "image/heic", heif: "image/heif", pdf: "application/pdf",
};

/**
 * The file's type, falling back to its extension: Chrome, Firefox and Windows often report
 * an empty type for .heic/.heif. Sent as the upload's contentType so the bucket accepts it.
 */
export function receiptContentType(file: { type: string; name?: string }): string {
  if (file.type) return file.type;
  const ext = (file.name ?? "").split(".").pop()?.toLowerCase() ?? "";
  return RECEIPT_TYPE_BY_EXT[ext] ?? "";
}

export function receiptProblem(file: { type: string; size: number; name?: string }): string | null {
  if (!RECEIPT_TYPES.includes(receiptContentType(file))) return "Receipts can be a photo (JPG, PNG, WebP, HEIC) or a PDF.";
  if (file.size > RECEIPT_MAX_BYTES) return "The receipt is over 10 MB.";
  return null;
}

/** <expense_id>/<timestamp>-<safe name>: the only shape attach_expense_receipt accepts. */
export function receiptPath(expenseId: string, fileName: string, now: number = Date.now()): string {
  const safe = fileName.normalize("NFKD")
    .replace(/[^\w.-]+/g, "_")
    .replace(/\.{2,}/g, ".")
    .replace(/_+/g, "_")
    .replace(/^[._]+/, "")
    .slice(-80) || "receipt";
  return `${expenseId}/${now}-${safe}`;
}
